export const fragments = {
  "nav": "<nav class=\"top-nav\">\n  <div class=\"nav-logo\">ÉCORCHÉ<span>.</span></div>\n  <div class=\"nav-links\">\n    <a href=\"#tracker\">Tracker</a>\n    <a href=\"#protocol\">Protocol</a>\n    <a href=\"#standards\">Standards</a>\n    <a href=\"#gauge\">Intensity</a>\n    <a href=\"#volume\">Volume</a>\n    <a href=\"#workout\">Workout</a>\n    <a href=\"#anatomy\">Anatomy</a>\n    <a href=\"#sources\">Sources</a>\n  </div>\n  <button class=\"hamburger-btn\" id=\"hamburgerBtn\" aria-label=\"Open menu\" aria-expanded=\"false\" onclick=\"toggleDrawer()\"><span></span></button>\n</nav>\n\n<div class=\"mobile-drawer\" id=\"mobileDrawer\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Navigation menu\">\n  <button class=\"mobile-drawer-close\" onclick=\"toggleDrawer(false)\" aria-label=\"Close menu\">\n    <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><path d=\"M6 6l12 12M18 6L6 18\"/></svg>\n  </button>\n  <a href=\"#tracker\" onclick=\"toggleDrawer(false)\">Tracker</a>\n  <a href=\"#protocol\" onclick=\"toggleDrawer(false)\">Protocol</a>\n  <a href=\"#standards\" onclick=\"toggleDrawer(false)\">Standards</a>\n  <a href=\"#gauge\" onclick=\"toggleDrawer(false)\">Intensity</a>\n  <a href=\"#volume\" onclick=\"toggleDrawer(false)\">Volume</a>\n  <a href=\"#workout\" onclick=\"toggleDrawer(false)\">Workout</a>\n  <a href=\"#anatomy\" onclick=\"toggleDrawer(false)\">Anatomy</a>\n  <a href=\"#sources\" onclick=\"toggleDrawer(false)\">Sources</a>\n  <a href=\"mailto:support@ecorche.app?subject=%C3%89CORCH%C3%89%20feedback\" class=\"drawer-feedback\" data-feedback onclick=\"toggleDrawer(false)\">Send feedback</a>\n</div>\n\n<div class=\"session-minibar\" id=\"sessionMinibar\">\n  <span class=\"mb-day\" id=\"mbDay\">Leg Day A</span>\n  <span class=\"mb-progress\" id=\"mbProgress\">0/21 sets</span>\n  <div class=\"mb-progress-ring\" aria-hidden=\"true\">\n    <svg width=\"30\" height=\"30\" viewBox=\"0 0 30 30\">\n      <circle class=\"mb-ring-track\" cx=\"15\" cy=\"15\" r=\"12\"></circle>\n      <circle class=\"mb-ring-fill\" id=\"mbRingFill\" cx=\"15\" cy=\"15\" r=\"12\" stroke-dasharray=\"75.4\" stroke-dashoffset=\"75.4\"></circle>\n    </svg>\n    <span class=\"mb-ring-text\" id=\"mbRingText\">0%</span>\n  </div>\n  <span class=\"mb-rest\" id=\"mbRest\"></span>\n  <button type=\"button\" class=\"mb-audio-btn\" id=\"mbAudioBtn\" onclick=\"toggleAudioAnnouncements()\" aria-label=\"Toggle rest-timer voice announcements\" title=\"Rest-timer voice announcements\" aria-pressed=\"true\"><svg id=\"mbAudioIcon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><polygon points=\"11 5 6 9 2 9 2 15 6 15 11 19 11 5\"></polygon><path d=\"M15.54 8.46a5 5 0 0 1 0 7.07\"></path><path d=\"M19.07 4.93a10 10 0 0 1 0 14.14\"></path></svg></button>\n  <button type=\"button\" class=\"mb-audio-btn\" id=\"mbHighContrastBtn\" onclick=\"toggleHighContrast()\" aria-label=\"Toggle high contrast gym mode\" title=\"High contrast gym mode\" aria-pressed=\"false\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><path d=\"M12 2a10 10 0 0 1 0 20z\" fill=\"currentColor\" stroke=\"none\"></path></svg></button>\n  <button type=\"button\" class=\"mb-audio-btn\" id=\"mbTempoBtn\" onclick=\"toggleTempoPacer()\" aria-label=\"Toggle tempo pacer (3 second lower, 1 second stretch hold, explosive up)\" title=\"Tempo pacer: 3-1-X\" aria-pressed=\"false\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><polyline points=\"12 6 12 12 16 14\"></polyline></svg></button>\n  <button type=\"button\" class=\"minibar-kiosk-btn\" id=\"kioskMinibarBtn\" onclick=\"toggleKioskMode()\">Start Workout</button>\n</div>",
  "hero": "<section class=\"hero\">\n  <div class=\"hero-bg\"></div>\n  <div class=\"hero-grid\"></div>\n  <div class=\"hero-particles\" id=\"heroParticles\"></div>\n  <div class=\"hero-content\">\n    <div class=\"hero-badge\" id=\"heroBadge\">Science-Backed Protocol</div>\n\n    <div class=\"group-tabs\" id=\"groupTabs\">\n      <button class=\"group-tab active\" data-tab-group=\"legs\" onclick=\"switchGroup('legs')\">Legs</button>\n      <button class=\"group-tab\" data-tab-group=\"push\" onclick=\"switchGroup('push')\">Push</button>\n      <button class=\"group-tab\" data-tab-group=\"pull\" onclick=\"switchGroup('pull')\">Pull</button>\n    </div>\n\n    <h1 id=\"heroTitle\">LEG DAY<br><span class=\"accent\" id=\"heroAccent\">PROTOCOL</span></h1>\n    <p class=\"hero-subtitle\" id=\"heroSubtitle\">An evidence-based 6-day Push / Pull / Legs A-B split. Built on the EMG and hypertrophy literature of Schoenfeld, Helms, Grgic, Maeo &amp; Nippard — one complete, science-backed program.</p>\n\n    <div class=\"day-toggle\">\n      <button class=\"day-toggle-btn active\" onclick=\"switchDay('A')\" id=\"btnDayA\">Day A</button>\n      <button class=\"day-toggle-btn\" onclick=\"switchDay('B')\" id=\"btnDayB\">Day B</button>\n    </div>\n\n    <div class=\"hero-stats\" id=\"heroStats\">\n      <div class=\"hero-stat\"><div class=\"num\" id=\"statEx\">7</div><div class=\"lbl\">Exercises</div></div>\n      <div class=\"hero-stat\"><div class=\"num\" id=\"statSets\">21</div><div class=\"lbl\">Working Sets</div></div>\n      <div class=\"hero-stat\"><div class=\"num\" id=\"statMuscles\">6</div><div class=\"lbl\">Muscle Groups</div></div>\n      <div class=\"hero-stat\"><div class=\"num\" id=\"statMin\">~65</div><div class=\"lbl\">Minutes</div></div>\n    </div>\n  </div>\n  <div class=\"scroll-cue\"><svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M12 5v14M5 12l7 7 7-7\"/></svg></div>\n</section>",
  "tracker": "<section class=\"section\" id=\"tracker\">\n  <div class=\"section-eyebrow reveal\">Your Week</div>\n  <h2 class=\"section-title reveal\">Weekly <span class=\"accent\">Progress Tracker</span></h2>\n  <p class=\"section-subtitle reveal\">Every set you log on any of the 6 days below is saved automatically in this browser, so your progress is still here next time you open this file. Tap a day card to jump straight to it.</p>\n  <div class=\"mesocycle-banner\" id=\"mesocycleBanner\"></div>\n\n  <div class=\"tracker-panel reveal\">\n    <div class=\"tracker-settings-row\">\n      <div class=\"unit-toggle\" role=\"group\" aria-label=\"Weight unit\">\n        <span class=\"unit-toggle-label\" aria-hidden=\"true\">Units</span>\n        <button type=\"button\" class=\"active\" data-unit=\"kg\" aria-pressed=\"true\" onclick=\"setWeightUnit('kg')\">kg</button>\n        <button type=\"button\" data-unit=\"lb\" aria-pressed=\"false\" onclick=\"setWeightUnit('lb')\">lb</button>\n      </div>\n      <label class=\"auto-rest-toggle\">\n        <input type=\"checkbox\" id=\"autoRestToggle\" checked onchange=\"setAutoRest(this.checked)\">\n        <span class=\"auto-rest-switch\" aria-hidden=\"true\"></span>\n        <span class=\"auto-rest-label\">\n          <span class=\"arl-title\">Auto-Rest</span>\n          <span class=\"arl-sub\">Start rest timer when a set is marked done</span>\n        </span>\n      </label>\n    </div>\n    <div class=\"tracker-top\">\n      <div class=\"tracker-ring-wrap\">\n        <svg viewBox=\"0 0 128 128\">\n          <defs>\n            <linearGradient id=\"trackerGradient\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n              <stop offset=\"0%\" stop-color=\"#369973\"/>\n              <stop offset=\"50%\" stop-color=\"#E8B23D\"/>\n              <stop offset=\"100%\" stop-color=\"#E45228\"/>\n            </linearGradient>\n          </defs>\n          <circle class=\"tracker-ring-bg\" cx=\"64\" cy=\"64\" r=\"54\"/>\n          <circle class=\"tracker-ring-fill\" id=\"masterRing\" cx=\"64\" cy=\"64\" r=\"54\" stroke-dasharray=\"339.3\" stroke-dashoffset=\"339.3\"/>\n        </svg>\n        <div class=\"tracker-ring-text\"><span class=\"big\" id=\"masterRingText\">0%</span><span class=\"small\" id=\"masterRingSets\">0/132 sets</span></div>\n      </div>\n      <div class=\"tracker-info\">\n        <h5>Full Week Completion</h5>\n        <p>Tracks every working set across all 6 sessions — Leg A/B, Push A/B and Pull A/B. Progress persists locally in this browser between visits.</p>\n      </div>\n    </div>\n\n    <div class=\"tracker-week-grid\" id=\"trackerWeekGrid\">\n      <button class=\"tracker-day-card\" data-jump=\"legs\" data-day=\"A\" onclick=\"jumpToDay('legs','A')\">\n        <div class=\"tracker-day-label\"><span>Session 01</span><span class=\"dot\" style=\"background:var(--frost);\"></span></div>\n        <div class=\"tracker-day-name\">Leg Day A</div>\n        <div class=\"tracker-day-bar\"><div class=\"tracker-day-bar-fill\" id=\"barLegsA\" style=\"transform:scaleX(0);background:var(--frost);\"></div></div>\n        <div class=\"tracker-day-count\" id=\"countLegsA\">0/21 sets</div>\n      </button>\n      <button class=\"tracker-day-card\" data-jump=\"push\" data-day=\"A\" onclick=\"jumpToDay('push','A')\">\n        <div class=\"tracker-day-label\"><span>Session 02</span><span class=\"dot\" style=\"background:var(--flame);\"></span></div>\n        <div class=\"tracker-day-name\">Push Day A</div>\n        <div class=\"tracker-day-bar\"><div class=\"tracker-day-bar-fill\" id=\"barPushA\" style=\"transform:scaleX(0);background:var(--flame);\"></div></div>\n        <div class=\"tracker-day-count\" id=\"countPushA\">0/21 sets</div>\n      </button>\n      <button class=\"tracker-day-card\" data-jump=\"pull\" data-day=\"A\" onclick=\"jumpToDay('pull','A')\">\n        <div class=\"tracker-day-label\"><span>Session 03</span><span class=\"dot\" style=\"background:var(--moss);\"></span></div>\n        <div class=\"tracker-day-name\">Pull Day A</div>\n        <div class=\"tracker-day-bar\"><div class=\"tracker-day-bar-fill\" id=\"barPullA\" style=\"transform:scaleX(0);background:var(--moss);\"></div></div>\n        <div class=\"tracker-day-count\" id=\"countPullA\">0/24 sets</div>\n      </button>\n      <button class=\"tracker-day-card\" data-jump=\"legs\" data-day=\"B\" onclick=\"jumpToDay('legs','B')\">\n        <div class=\"tracker-day-label\"><span>Session 04</span><span class=\"dot\" style=\"background:var(--frost);\"></span></div>\n        <div class=\"tracker-day-name\">Leg Day B</div>\n        <div class=\"tracker-day-bar\"><div class=\"tracker-day-bar-fill\" id=\"barLegsB\" style=\"transform:scaleX(0);background:var(--frost);\"></div></div>\n        <div class=\"tracker-day-count\" id=\"countLegsB\">0/21 sets</div>\n      </button>\n      <button class=\"tracker-day-card\" data-jump=\"push\" data-day=\"B\" onclick=\"jumpToDay('push','B')\">\n        <div class=\"tracker-day-label\"><span>Session 05</span><span class=\"dot\" style=\"background:var(--flame);\"></span></div>\n        <div class=\"tracker-day-name\">Push Day B</div>\n        <div class=\"tracker-day-bar\"><div class=\"tracker-day-bar-fill\" id=\"barPushB\" style=\"transform:scaleX(0);background:var(--flame);\"></div></div>\n        <div class=\"tracker-day-count\" id=\"countPushB\">0/21 sets</div>\n      </button>\n      <button class=\"tracker-day-card\" data-jump=\"pull\" data-day=\"B\" onclick=\"jumpToDay('pull','B')\">\n        <div class=\"tracker-day-label\"><span>Session 06</span><span class=\"dot\" style=\"background:var(--moss);\"></span></div>\n        <div class=\"tracker-day-name\">Pull Day B</div>\n        <div class=\"tracker-day-bar\"><div class=\"tracker-day-bar-fill\" id=\"barPullB\" style=\"transform:scaleX(0);background:var(--moss);\"></div></div>\n        <div class=\"tracker-day-count\" id=\"countPullB\">0/24 sets</div>\n      </button>\n    </div>\n\n    <div class=\"tracker-reset-all\">\n      <button class=\"reset-btn\" onclick=\"openHistoryModal()\">View History</button>\n      <button class=\"reset-btn\" onclick=\"exportProgress()\">Export Backup</button>\n      <button class=\"reset-btn\" onclick=\"exportCSV()\">Export CSV</button>\n      <button class=\"reset-btn\" id=\"autoBackupBtn\" onclick=\"toggleAutoBackup()\">Enable Auto-Backup</button>\n      <button class=\"reset-btn\" onclick=\"document.getElementById('importFileInput').click()\">Import Backup</button>\n      <input type=\"file\" id=\"importFileInput\" aria-label=\"Backup file to import\" accept=\"application/json\" style=\"display:none\" onchange=\"importProgress(this.files[0])\">\n      <button class=\"reset-btn\" onclick=\"confirmResetAll()\">Reset Entire Week</button>\n    </div>\n  </div>\n</section>",
  "anatomy": "<section class=\"section anatomy-section\" id=\"anatomy\">\n  <div class=\"section-eyebrow reveal\">Muscle Infographic</div>\n  <h2 class=\"section-title reveal\">The <span class=\"accent\">Engagement</span> Map</h2>\n  <p class=\"section-subtitle reveal\">Where every set across all 6 sessions actually lands, down to the muscle and the approximate share of the work — and why the exercise selection is built around it. Switch tabs to explore each day's muscles.</p>\n\n  <div class=\"group-tabs reveal\" id=\"anatomyTabs\">\n    <button class=\"group-tab\" data-tab-group=\"push\" onclick=\"switchAnatomyTab('push')\">Push</button>\n    <button class=\"group-tab\" data-tab-group=\"pull\" onclick=\"switchAnatomyTab('pull')\">Pull</button>\n    <button class=\"group-tab active\" data-tab-group=\"legs\" onclick=\"switchAnatomyTab('legs')\">Legs</button>\n  </div>\n\n  <div class=\"anatomy-panel\" data-group=\"push\">\n\n  <div class=\"silhouette-panel reveal\">\n    <div>\n      <svg viewBox=\"0 0 400 420\" class=\"silhouette-svg\">\n        <!-- base figure -->\n        <circle class=\"sil-base\" cx=\"200\" cy=\"55\" r=\"30\"/>\n        <rect class=\"sil-base\" x=\"186\" y=\"80\" width=\"28\" height=\"20\" rx=\"6\"/>\n        <path class=\"sil-base\" d=\"M130,100 C130,94 270,94 270,100 L258,270 C256,300 144,300 142,270 Z\"/>\n        <rect class=\"sil-base\" x=\"68\" y=\"108\" width=\"46\" height=\"185\" rx=\"23\"/>\n        <rect class=\"sil-base\" x=\"286\" y=\"108\" width=\"46\" height=\"185\" rx=\"23\"/>\n        <!-- upper chest -->\n        <ellipse class=\"sil-zone zone-chest-upper\" cx=\"200\" cy=\"140\" rx=\"62\" ry=\"24\"/>\n        <!-- lower chest -->\n        <ellipse class=\"sil-zone zone-chest-lower\" cx=\"200\" cy=\"188\" rx=\"58\" ry=\"28\"/>\n        <!-- delts -->\n        <circle class=\"sil-zone zone-delt\" cx=\"98\" cy=\"120\" r=\"27\"/>\n        <circle class=\"sil-zone zone-delt\" cx=\"302\" cy=\"120\" r=\"27\"/>\n        <!-- abs -->\n        <rect class=\"sil-zone zone-abs\" x=\"172\" y=\"264\" width=\"56\" height=\"82\" rx=\"16\"/>\n        <line class=\"zone-line\" x1=\"172\" y1=\"292\" x2=\"228\" y2=\"292\"/>\n        <line class=\"zone-line\" x1=\"172\" y1=\"318\" x2=\"228\" y2=\"318\"/>\n        <line class=\"zone-line\" x1=\"200\" y1=\"264\" x2=\"200\" y2=\"346\"/>\n      </svg>\n    </div>\n    <div class=\"silhouette-legend\">\n      <div class=\"legend-row\">\n        <div class=\"legend-dot\" style=\"background:var(--flame);\"></div>\n        <div><h5>Upper Chest — Clavicular Head<span class=\"pct-tag\">peaks ~44° incline</span></h5><p>Hit hardest by incline dumbbell &amp; Smith presses. The steeper the angle, the more work shifts here — and off the sternal fibers below.</p></div>\n      </div>\n      <div class=\"legend-row\">\n        <div class=\"legend-dot\" style=\"background:var(--flame-dim);\"></div>\n        <div><h5>Mid/Lower Chest — Sternocostal Head<span class=\"pct-tag\">peaks at 0° flat</span></h5><p>The biggest portion of the pec by mass. Flat pressing and cable crossovers with a high pulley both bias this region hardest.</p></div>\n      </div>\n      <div class=\"legend-row\">\n        <div class=\"legend-dot\" style=\"background:var(--gold);\"></div>\n        <div><h5>Front &amp; Lateral Deltoid</h5><p>Front delt rides along on every press; lateral delt only grows meaningfully from direct raises — it's largely a bystander during pressing movements.</p></div>\n      </div>\n      <div class=\"legend-row\">\n        <div class=\"legend-dot\" style=\"background:var(--teal);\"></div>\n        <div><h5>Rectus Abdominis</h5><p>Trained at both ends of its function this program: spinal flexion (cable crunch) on Day A, hip flexion (hanging leg raise) on Day B.</p></div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"muscle-grid reveal\">\n\n    <div class=\"muscle-card chest\">\n      <div class=\"muscle-card-header\">\n        <div class=\"muscle-icon chest\">&#128293;</div>\n        <div><h3>Chest</h3><p class=\"latin\">M. pectoralis major</p></div>\n      </div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Primary Exercises</span><span class=\"muscle-stat-value\">Flat/Incline Press, Cable Crossover</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Optimal Rep Range</span><span class=\"muscle-stat-value\">3-15 reps</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Weekly Volume Target</span><span class=\"muscle-stat-value\">12-20 hard sets</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Fiber Profile</span><span class=\"muscle-stat-value\">Fast-twitch dominant</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Growth Mechanism</span><span class=\"muscle-stat-value\">Mechanical Tension + Stretch</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Key Study</span><span class=\"muscle-stat-value\">Trebs et al. (2010) — angle vs. head bias</span></div>\n    </div>\n\n    <div class=\"muscle-card delt\">\n      <div class=\"muscle-card-header\">\n        <div class=\"muscle-icon delt\">&#9889;</div>\n        <div><h3>Deltoids</h3><p class=\"latin\">M. deltoideus (anterior, lateral)</p></div>\n      </div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Primary Exercises</span><span class=\"muscle-stat-value\">Machine Press, Lateral Raise</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Optimal Rep Range</span><span class=\"muscle-stat-value\">8-20 reps</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Weekly Volume Target</span><span class=\"muscle-stat-value\">6-10 direct sets</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Fiber Profile</span><span class=\"muscle-stat-value\">Fast-twitch dominant</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Growth Mechanism</span><span class=\"muscle-stat-value\">High-Rep Peak Contraction</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Key Study</span><span class=\"muscle-stat-value\">Larsen, Wolf, Schoenfeld (2025)</span></div>\n    </div>\n\n    <div class=\"muscle-card tri\">\n      <div class=\"muscle-card-header\">\n        <div class=\"muscle-icon tri\">&#128170;</div>\n        <div><h3>Triceps Brachii</h3><p class=\"latin\">Long, lateral &amp; medial heads</p></div>\n      </div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Primary Exercises</span><span class=\"muscle-stat-value\">Overhead Extension, Pushdown</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Optimal Rep Range</span><span class=\"muscle-stat-value\">8-15 reps</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Weekly Volume Target</span><span class=\"muscle-stat-value\">10-16 hard sets</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Fiber Profile</span><span class=\"muscle-stat-value\">Mixed across 3 heads</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Growth Mechanism</span><span class=\"muscle-stat-value\">Long-Length Loading (Long Head)</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Key Study</span><span class=\"muscle-stat-value\">Maeo et al. (2022) — 28.5% vs 19.6%</span></div>\n      <div class=\"tri-head-panel\">\n        <svg viewBox=\"0 0 200 200\" class=\"tri-head-svg\">\n          <ellipse class=\"head-long\" cx=\"100\" cy=\"72\" rx=\"46\" ry=\"36\"/>\n          <ellipse class=\"head-lateral\" cx=\"66\" cy=\"122\" rx=\"36\" ry=\"30\"/>\n          <ellipse class=\"head-medial\" cx=\"132\" cy=\"124\" rx=\"30\" ry=\"26\"/>\n        </svg>\n        <div>\n          <div class=\"tri-legend-row\"><strong style=\"color:var(--violet-bright);\">Long Head</strong> crosses shoulder + elbow — only lengthens under an overhead arm position.</div>\n          <div class=\"tri-legend-row\"><strong style=\"color:var(--violet-bright);\">Lateral Head</strong> gives the visible \"horseshoe\" — most active in pushdowns.</div>\n          <div class=\"tri-legend-row\"><strong style=\"color:var(--violet-bright);\">Medial Head</strong> sits deep, active across nearly every extension variation.</div>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"muscle-card core\">\n      <div class=\"muscle-card-header\">\n        <div class=\"muscle-icon core\">&#128737;</div>\n        <div><h3>Core</h3><p class=\"latin\">M. rectus abdominis</p></div>\n      </div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Primary Exercises</span><span class=\"muscle-stat-value\">Cable Crunch, Hanging Leg Raise</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Optimal Rep Range</span><span class=\"muscle-stat-value\">10-20 / to failure</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Weekly Volume Target</span><span class=\"muscle-stat-value\">8-12 hard sets</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Fiber Profile</span><span class=\"muscle-stat-value\">Mixed</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Growth Mechanism</span><span class=\"muscle-stat-value\">Resisted Spinal / Hip Flexion</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Key Study</span><span class=\"muscle-stat-value\">Schoenfeld et al. (2017) — volume dose-response</span></div>\n    </div>\n\n  </div>\n\n  <!-- Comparison Tables -->\n  <h3 style=\"margin-top:52px;margin-bottom:20px;font-size:18px;font-weight:700;color:var(--ink);\" class=\"reveal\">Exercise Comparison — Chest Activation by Bench Angle</h3>\n  <div class=\"reveal\" style=\"overflow-x:auto;\">\n    <table class=\"comparison-table\">\n      <thead><tr><th>Bench Angle</th><th>Upper (Clavicular)</th><th>Mid/Lower (Sternocostal)</th><th>Front Delt</th><th>Best For</th></tr></thead>\n      <tbody>\n        <tr><td>Flat (0°)</td><td>55%</td><td>95%</td><td>60%</td><td>Overall Mass, Lower Fibers</td></tr>\n        <tr><td>Incline (~30°)</td><td>85%</td><td>75%</td><td>68%</td><td>Balanced Upper Chest</td></tr>\n        <tr><td>Incline (~44-45°)</td><td>92%</td><td>60%</td><td>78%</td><td>Maximum Clavicular Bias</td></tr>\n      </tbody>\n    </table>\n  </div>\n  <p class=\"source-note reveal\" style=\"margin-top:12px;\">Values are illustrative % of MVIC, directionally consistent with controlled EMG testing. Source: Trebs, Brandenburg &amp; Pitney (2010); Rodríguez-Ridao et al. (2020).</p>\n\n  <h3 style=\"margin-top:48px;margin-bottom:20px;font-size:18px;font-weight:700;color:var(--ink);\" class=\"reveal\">Exercise Comparison — Triceps Head Activation</h3>\n  <div class=\"reveal\" style=\"overflow-x:auto;\">\n    <table class=\"comparison-table\">\n      <thead><tr><th>Exercise</th><th>Long Head</th><th>Lateral Head</th><th>Medial Head</th><th>Best For</th></tr></thead>\n      <tbody>\n        <tr><td>Cable Pushdown</td><td>45%</td><td>88%</td><td>70%</td><td>Lateral Head Peak</td></tr>\n        <tr><td>Dumbbell Kickback</td><td>40%</td><td>80%</td><td>60%</td><td>Isolated Peak Squeeze</td></tr>\n        <tr><td>Overhead Extension</td><td>92%</td><td>55%</td><td>58%</td><td>Long Head Hypertrophy</td></tr>\n      </tbody>\n    </table>\n  </div>\n  <p class=\"source-note reveal\" style=\"margin-top:12px;\">Source: Maeo et al. (2022) — overhead-position elbow extension training produced 28.5% long-head muscle growth vs. 19.6% for the neutral arm position over 12 weeks.</p>\n  </div>\n  <div class=\"anatomy-panel\" data-group=\"pull\">\n\n  <div class=\"silhouette-panel reveal\">\n    <div>\n      <svg viewBox=\"0 0 400 420\" class=\"silhouette-svg\">\n        <!-- base figure, back view -->\n        <circle class=\"sil-base\" cx=\"200\" cy=\"52\" r=\"28\"/>\n        <rect class=\"sil-base\" x=\"188\" y=\"76\" width=\"24\" height=\"18\" rx=\"5\"/>\n        <path class=\"sil-base\" d=\"M138,92 C138,86 262,86 262,92 L246,270 C244,300 156,300 154,270 Z\"/>\n        <rect class=\"sil-base\" x=\"62\" y=\"100\" width=\"44\" height=\"190\" rx=\"22\"/>\n        <rect class=\"sil-base\" x=\"294\" y=\"100\" width=\"44\" height=\"190\" rx=\"22\"/>\n        <!-- traps -->\n        <polygon class=\"sil-zone zone-traps\" points=\"200,96 244,132 200,158 156,132\"/>\n        <!-- lats (fan out from spine) -->\n        <ellipse class=\"sil-zone zone-lats\" cx=\"150\" cy=\"200\" rx=\"40\" ry=\"70\"/>\n        <ellipse class=\"sil-zone zone-lats\" cx=\"250\" cy=\"200\" rx=\"40\" ry=\"70\"/>\n        <!-- rear delts -->\n        <circle class=\"sil-zone zone-reardelt\" cx=\"100\" cy=\"112\" r=\"24\"/>\n        <circle class=\"sil-zone zone-reardelt\" cx=\"300\" cy=\"112\" r=\"24\"/>\n        <!-- biceps -->\n        <ellipse class=\"sil-zone zone-bicep\" cx=\"84\" cy=\"168\" rx=\"20\" ry=\"34\"/>\n        <ellipse class=\"sil-zone zone-bicep\" cx=\"316\" cy=\"168\" rx=\"20\" ry=\"34\"/>\n        <!-- forearms -->\n        <rect class=\"sil-zone zone-forearm\" x=\"66\" y=\"210\" width=\"34\" height=\"72\" rx=\"14\"/>\n        <rect class=\"sil-zone zone-forearm\" x=\"300\" y=\"210\" width=\"34\" height=\"72\" rx=\"14\"/>\n        <line class=\"zone-line\" x1=\"200\" y1=\"96\" x2=\"200\" y2=\"300\"/>\n      </svg>\n    </div>\n    <div class=\"silhouette-legend\">\n      <div class=\"legend-row\">\n        <div class=\"legend-dot\" style=\"background:var(--moss);\"></div>\n        <div><h5>Latissimus Dorsi — The V-Taper Engine<span class=\"pct-tag\">peaks with pronated grip</span></h5><p>Hit hardest by pulldowns, rows and straight-arm pullovers. Controlled research shows grip pronation, not grip width, is what actually recruits it hardest.</p></div>\n      </div>\n      <div class=\"legend-row\">\n        <div class=\"legend-dot\" style=\"background:var(--gold);\"></div>\n        <div><h5>Mid-Back — Traps &amp; Rhomboids<span class=\"pct-tag\">peaks under scapular retraction</span></h5><p>Chest-supported rows and flexion rows, built around a hard end-range squeeze, target this region more directly than any lat-focused pull.</p></div>\n      </div>\n      <div class=\"legend-row\">\n        <div class=\"legend-dot\" style=\"background:var(--violet);\"></div>\n        <div><h5>Rear Deltoid<span class=\"pct-tag\">hip-height cable, constant tension</span></h5><p>Rides along passively during rowing, but only grows fully from direct reverse-crossover work that matches its horizontal-abduction strength curve.</p></div>\n      </div>\n      <div class=\"legend-row\">\n        <div class=\"legend-dot\" style=\"background:var(--steel);\"></div>\n        <div><h5>Biceps — Long &amp; Short Head<span class=\"pct-tag\">long head peaks in shoulder extension</span></h5><p>Face-away and incline positions stretch the long head behind the torso plane, producing the deepest EMG activation of any curl variation tested.</p></div>\n      </div>\n      <div class=\"legend-row\">\n        <div class=\"legend-dot\" style=\"background:var(--ember);\"></div>\n        <div><h5>Forearms — Flexors &amp; Extensors<span class=\"pct-tag\">trained to true failure</span></h5><p>Small, fast-recovering muscles that respond best to frequent, high-rep, failure-based finishing work on both sides of the forearm.</p></div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"muscle-grid\">\n\n    <div class=\"muscle-card lat\">\n      <div class=\"muscle-card-header\">\n        <div class=\"muscle-icon lat\">&#127942;</div>\n        <div><h3>Latissimus Dorsi</h3><p class=\"latin\">M. latissimus dorsi</p></div>\n      </div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Primary Exercises</span><span class=\"muscle-stat-value\">Lat Pulldown, Pullover</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Optimal Rep Range</span><span class=\"muscle-stat-value\">8-15 reps</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Weekly Volume Target</span><span class=\"muscle-stat-value\">12-18 hard sets</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Fiber Profile</span><span class=\"muscle-stat-value\">Large, fan-shaped, mixed</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Growth Mechanism</span><span class=\"muscle-stat-value\">Stretch-Mediated + Pronated Grip</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Key Study</span><span class=\"muscle-stat-value\">Andersen et al. (2014) — grip effects</span></div>\n    </div>\n\n    <div class=\"muscle-card midback\">\n      <div class=\"muscle-card-header\">\n        <div class=\"muscle-icon midback\">&#128170;</div>\n        <div><h3>Mid-Back</h3><p class=\"latin\">Rhomboids &amp; mid trapezius</p></div>\n      </div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Primary Exercises</span><span class=\"muscle-stat-value\">Chest-Supported Row, Flexion Row</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Optimal Rep Range</span><span class=\"muscle-stat-value\">8-12 reps</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Weekly Volume Target</span><span class=\"muscle-stat-value\">10-14 hard sets</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Fiber Profile</span><span class=\"muscle-stat-value\">Postural, endurance-biased</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Growth Mechanism</span><span class=\"muscle-stat-value\">Scapular Retraction Under Load</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Key Study</span><span class=\"muscle-stat-value\">Long-length training principle</span></div>\n    </div>\n\n    <div class=\"muscle-card reardelt\">\n      <div class=\"muscle-card-header\">\n        <div class=\"muscle-icon reardelt\">&#127919;</div>\n        <div><h3>Rear Deltoid</h3><p class=\"latin\">Posterior deltoid fibers</p></div>\n      </div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Primary Exercises</span><span class=\"muscle-stat-value\">Reverse Cable Crossover</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Optimal Rep Range</span><span class=\"muscle-stat-value\">12-20 reps</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Weekly Volume Target</span><span class=\"muscle-stat-value\">8-12 hard sets</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Fiber Profile</span><span class=\"muscle-stat-value\">Small, fast-fatiguing</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Growth Mechanism</span><span class=\"muscle-stat-value\">Constant-Tension Horizontal Abduction</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Key Study</span><span class=\"muscle-stat-value\">Signorile et al. (2002) — hand position EMG</span></div>\n    </div>\n\n    <div class=\"muscle-card bicep\">\n      <div class=\"muscle-card-header\">\n        <div class=\"muscle-icon bicep\">&#128170;</div>\n        <div><h3>Biceps Brachii</h3><p class=\"latin\">Long &amp; short heads</p></div>\n      </div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Primary Exercises</span><span class=\"muscle-stat-value\">Bayesian Curl, Incline Curl</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Optimal Rep Range</span><span class=\"muscle-stat-value\">8-15 reps</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Weekly Volume Target</span><span class=\"muscle-stat-value\">10-16 hard sets</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Fiber Profile</span><span class=\"muscle-stat-value\">Long head stretch-sensitive</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Growth Mechanism</span><span class=\"muscle-stat-value\">Long-Length Loading (Behind Torso)</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Key Study</span><span class=\"muscle-stat-value\">Oliveira et al. (2009) — shoulder position</span></div>\n      <div class=\"tri-head-panel\">\n        <svg viewBox=\"0 0 200 200\" class=\"tri-head-svg\">\n          <ellipse class=\"head-long\" cx=\"100\" cy=\"72\" rx=\"46\" ry=\"36\"/>\n          <ellipse class=\"head-lateral\" cx=\"66\" cy=\"122\" rx=\"36\" ry=\"30\"/>\n          <ellipse class=\"head-medial\" cx=\"132\" cy=\"124\" rx=\"30\" ry=\"26\"/>\n        </svg>\n        <div>\n          <div class=\"tri-legend-row\"><strong style=\"color:var(--steel-bright);\">Long Head</strong> crosses the shoulder — only reaches full stretch with the arm extended behind the torso.</div>\n          <div class=\"tri-legend-row\"><strong style=\"color:var(--steel-bright);\">Short Head</strong> sits inner/front — dominant during preacher and concentration positions.</div>\n          <div class=\"tri-legend-row\"><strong style=\"color:var(--steel-bright);\">Brachialis</strong> sits underneath both heads — hammer and neutral grips shift load onto it directly.</div>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"muscle-card forearm\">\n      <div class=\"muscle-card-header\">\n        <div class=\"muscle-icon forearm\">&#9995;</div>\n        <div><h3>Forearms</h3><p class=\"latin\">Flexors, extensors &amp; brachioradialis</p></div>\n      </div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Primary Exercises</span><span class=\"muscle-stat-value\">Wrist Curl, Reverse Barbell Curl</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Optimal Rep Range</span><span class=\"muscle-stat-value\">To failure, high rep</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Weekly Volume Target</span><span class=\"muscle-stat-value\">6-10 hard sets per side</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Fiber Profile</span><span class=\"muscle-stat-value\">Flexors (grip) vs. extensors (stability)</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Growth Mechanism</span><span class=\"muscle-stat-value\">High-Frequency Failure Overload</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Key Study</span><span class=\"muscle-stat-value\">Schoenfeld et al. (2017) — volume dose-response</span></div>\n    </div>\n\n  </div>\n\n  <!-- Comparison Tables -->\n  <h3 style=\"margin-top:52px;margin-bottom:20px;font-size:18px;font-weight:700;color:var(--ink);\" class=\"reveal\">Exercise Comparison — Lat Activation by Grip Width &amp; Orientation</h3>\n  <div class=\"reveal\" style=\"overflow-x:auto;\">\n    <table class=\"comparison-table\">\n      <thead><tr><th>Grip / Orientation</th><th>Lat Activation</th><th>Biceps Activation</th><th>Best For</th></tr></thead>\n      <tbody>\n        <tr><td>Wide Pronated</td><td>92%</td><td>45%</td><td>Vertical Width &amp; Teres Major</td></tr>\n        <tr><td>Medium Pronated</td><td>90%</td><td>52%</td><td>Balanced Lat Recruitment</td></tr>\n        <tr><td>Narrow/Close Pronated</td><td>88%</td><td>65%</td><td>Lat Sweep + Biceps Carryover</td></tr>\n        <tr><td>Supinated (Chin-Up Grip)</td><td>80%</td><td>78%</td><td>Biceps-Dominant Carryover</td></tr>\n      </tbody>\n    </table>\n  </div>\n  <p class=\"source-note reveal\" style=\"margin-top:12px;\">Values are illustrative % of MVIC, directionally consistent with controlled EMG testing. Source: Andersen, Fimland, Wiik, Skoglund &amp; Sæterbakken (2014); Lusk, Hale &amp; Russell (2010).</p>\n\n  <h3 style=\"margin-top:48px;margin-bottom:20px;font-size:18px;font-weight:700;color:var(--ink);\" class=\"reveal\">Exercise Comparison — Biceps Long Head Activation by Curl Variation</h3>\n  <div class=\"reveal\" style=\"overflow-x:auto;\">\n    <table class=\"comparison-table\">\n      <thead><tr><th>Exercise</th><th>Shoulder Position</th><th>Long Head EMG</th><th>Best For</th></tr></thead>\n      <tbody>\n        <tr><td>Incline Dumbbell Curl</td><td>Extended behind torso</td><td>91%</td><td>Long Head Mass</td></tr>\n        <tr><td>Face-Away Bayesian Curl</td><td>Extended behind torso</td><td>89%</td><td>Long Head Peak Stretch</td></tr>\n        <tr><td>Standard Dumbbell Curl</td><td>Neutral, arm at side</td><td>80%</td><td>General Mass</td></tr>\n        <tr><td>Preacher Curl</td><td>Flexed in front of torso</td><td>60%</td><td>Short Head / Brachialis</td></tr>\n      </tbody>\n    </table>\n  </div>\n  <p class=\"source-note reveal\" style=\"margin-top:12px;\">Source: Oliveira, Matta, Alves, Garcia &amp; Vieira (2009) — biceps brachii activation was consistently greatest when the muscle was worked at a longer length; corroborated by a 2025 exploratory EMG comparison of traditional dumbbell versus Bayesian cable curls.</p>\n  </div>\n  <div class=\"anatomy-panel active\" data-group=\"legs\">\n\n  <div class=\"silhouette-panel reveal\">\n    <div>\n      <svg viewBox=\"0 0 320 460\" class=\"silhouette-svg\">\n        <!-- base figure: pelvis + two legs -->\n        <path class=\"sil-base\" d=\"M110,30 C110,24 210,24 210,30 L218,130 C220,150 100,150 102,130 Z\"/>\n        <rect class=\"sil-base\" x=\"98\" y=\"128\" width=\"52\" height=\"230\" rx=\"26\"/>\n        <rect class=\"sil-base\" x=\"170\" y=\"128\" width=\"52\" height=\"230\" rx=\"26\"/>\n        <ellipse class=\"sil-base\" cx=\"124\" cy=\"378\" rx=\"30\" ry=\"16\"/>\n        <ellipse class=\"sil-base\" cx=\"196\" cy=\"378\" rx=\"30\" ry=\"16\"/>\n        <!-- glutes -->\n        <ellipse class=\"sil-zone zone-glute\" cx=\"124\" cy=\"105\" rx=\"30\" ry=\"26\"/>\n        <ellipse class=\"sil-zone zone-glute\" cx=\"196\" cy=\"105\" rx=\"30\" ry=\"26\"/>\n        <!-- quads (front of thigh) -->\n        <ellipse class=\"sil-zone zone-quad\" cx=\"124\" cy=\"210\" rx=\"24\" ry=\"62\"/>\n        <ellipse class=\"sil-zone zone-quad\" cx=\"196\" cy=\"210\" rx=\"24\" ry=\"62\"/>\n        <!-- hamstrings (back of thigh, offset) -->\n        <ellipse class=\"sil-zone zone-ham\" cx=\"124\" cy=\"230\" rx=\"16\" ry=\"48\" opacity=\"0.55\"/>\n        <ellipse class=\"sil-zone zone-ham\" cx=\"196\" cy=\"230\" rx=\"16\" ry=\"48\" opacity=\"0.55\"/>\n        <!-- calves -->\n        <ellipse class=\"sil-zone zone-calf\" cx=\"124\" cy=\"325\" rx=\"20\" ry=\"42\"/>\n        <ellipse class=\"sil-zone zone-calf\" cx=\"196\" cy=\"325\" rx=\"20\" ry=\"42\"/>\n      </svg>\n    </div>\n    <div class=\"silhouette-legend\">\n      <div class=\"legend-row\">\n        <div class=\"legend-dot\" style=\"background:var(--frost);\"></div>\n        <div><h5>Quadriceps<span class=\"pct-tag\">rectus femoris peaks in reclined position</span></h5><p>Back squat and leg press build raw mass; the leaned-back leg extension isolates the rectus femoris at its longest usable length.</p></div>\n      </div>\n      <div class=\"legend-row\">\n        <div class=\"legend-dot\" style=\"background:var(--ham);\"></div>\n        <div><h5>Hamstrings<span class=\"pct-tag\">RDL trains at long muscle length</span></h5><p>With leg curls out of the program, RDLs carry the full direct hamstring stimulus — a hip-flexed, long-length position, which the research below still favors over short-length training.</p></div>\n      </div>\n      <div class=\"legend-row\">\n        <div class=\"legend-dot\" style=\"background:var(--glute);\"></div>\n        <div><h5>Glutes</h5><p>Never trained in true isolation here — they ride along on every squat and hinge pattern as a secondary mover, which is enough volume for most lifters.</p></div>\n      </div>\n      <div class=\"legend-row\">\n        <div class=\"legend-dot\" style=\"background:var(--calf);\"></div>\n        <div><h5>Calves — Gastrocnemius &amp; Soleus</h5><p>Two distinct muscles needing two distinct knee angles: straight-leg standing raises for the gastrocnemius, bent-knee seated raises for the soleus underneath.</p></div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"muscle-grid reveal\">\n\n    <div class=\"muscle-card quad\">\n      <div class=\"muscle-card-header\"><div class=\"muscle-icon quad\">&#129461;</div><div><h3>Quadriceps</h3><p class=\"latin\">M. quadriceps femoris</p></div></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Primary Exercises</span><span class=\"muscle-stat-value\">Barbell Back Squat, Leg Press, Leg Extension</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Optimal Rep Range</span><span class=\"muscle-stat-value\">8-20 reps</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Weekly Volume Target</span><span class=\"muscle-stat-value\">12-20 hard sets</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Fiber Profile</span><span class=\"muscle-stat-value\">Fast-twitch dominant</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Growth Mechanism</span><span class=\"muscle-stat-value\">Mechanical Tension + Stretch</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Key Study</span><span class=\"muscle-stat-value\">Pedrosa et al. (2022) — length-biased ROM</span></div>\n    </div>\n\n    <div class=\"muscle-card ham\">\n      <div class=\"muscle-card-header\"><div class=\"muscle-icon ham\">&#129470;</div><div><h3>Hamstrings</h3><p class=\"latin\">M. biceps femoris, semitendinosus, semimembranosus</p></div></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Primary Exercises</span><span class=\"muscle-stat-value\">Romanian Deadlifts (Barbell/Dumbbell)</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Optimal Rep Range</span><span class=\"muscle-stat-value\">8-12 reps</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Weekly Volume Target</span><span class=\"muscle-stat-value\">10-16 hard sets</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Fiber Profile</span><span class=\"muscle-stat-value\">Fast-twitch dominant</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Growth Mechanism</span><span class=\"muscle-stat-value\">Long-Length (Hip-Flexed) Loading</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Key Study</span><span class=\"muscle-stat-value\">Maeo et al. (2021) — 14.1% vs 9.3%</span></div>\n    </div>\n\n    <div class=\"muscle-card glute\">\n      <div class=\"muscle-card-header\"><div class=\"muscle-icon glute\">&#127947;</div><div><h3>Glutes</h3><p class=\"latin\">M. gluteus maximus, medius, minimus</p></div></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Primary Exercises</span><span class=\"muscle-stat-value\">RDLs, Back Squat, Leg Press</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Optimal Rep Range</span><span class=\"muscle-stat-value\">8-15 reps</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Weekly Volume Target</span><span class=\"muscle-stat-value\">10-16 indirect + direct sets</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Fiber Profile</span><span class=\"muscle-stat-value\">Mixed</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Growth Mechanism</span><span class=\"muscle-stat-value\">Hip Extension Under Load</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Key Study</span><span class=\"muscle-stat-value\">Schoenfeld et al. (2017) — volume dose-response</span></div>\n    </div>\n\n    <div class=\"muscle-card calf\">\n      <div class=\"muscle-card-header\"><div class=\"muscle-icon calf\">&#128098;</div><div><h3>Calves</h3><p class=\"latin\">M. gastrocnemius, soleus</p></div></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Primary Exercises</span><span class=\"muscle-stat-value\">Standing &amp; Seated Calf Raises</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Optimal Rep Range</span><span class=\"muscle-stat-value\">10-20 / to failure</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Weekly Volume Target</span><span class=\"muscle-stat-value\">12-20 hard sets</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Fiber Profile</span><span class=\"muscle-stat-value\">Gastroc fast-twitch leaning / Soleus slow-twitch dominant</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Growth Mechanism</span><span class=\"muscle-stat-value\">Lengthened-Position Loading</span></div>\n      <div class=\"muscle-stat-row\"><span class=\"muscle-stat-label\">Key Study</span><span class=\"muscle-stat-value\">Kassiano et al. (2023) — 15.2% vs 6.7%</span></div>\n    </div>\n\n  </div>\n\n  <h3 style=\"margin-top:52px;margin-bottom:20px;font-size:18px;font-weight:700;color:var(--ink);\" class=\"reveal\">Exercise Comparison — Hamstring Length &amp; Growth</h3>\n  <p class=\"section-subtitle reveal\" style=\"margin-bottom:16px;\">Leg Curls aren't currently programmed — RDLs now carry the hamstrings' full direct volume — but the underlying muscle-length research is still worth knowing if you ever want to add a curl variation back in.</p>\n  <div class=\"reveal\" style=\"overflow-x:auto;\">\n    <table class=\"comparison-table\">\n      <thead><tr><th>Leg Curl Position</th><th>Hip Angle</th><th>Muscle Length</th><th>12-Week Hypertrophy</th><th>Best For</th></tr></thead>\n      <tbody>\n        <tr><td>Lying</td><td>Extended (~180°)</td><td>Short</td><td>+9.3%</td><td>CNS-Fresh Early Isolation</td></tr>\n        <tr><td>Seated</td><td>Flexed (~90°)</td><td>Long</td><td>+14.1%</td><td>Maximum Hamstring Growth</td></tr>\n        <tr><td>Romanian Deadlift <span style=\"color:var(--ink-muted);\">(programmed)</span></td><td>Flexed at hip, extended at knee</td><td>Long (hip-hinge)</td><td>—</td><td>Current program's only direct driver</td></tr>\n      </tbody>\n    </table>\n  </div>\n  <p class=\"source-note reveal\" style=\"margin-top:12px;\">Source: Maeo et al. (2021), Med Sci Sports Exerc 53(4):825-837 — 12-week trial, MRI-measured whole-hamstring muscle volume, biceps femoris long head showed the largest gap between conditions.</p>\n\n  <h3 style=\"margin-top:48px;margin-bottom:20px;font-size:18px;font-weight:700;color:var(--ink);\" class=\"reveal\">Exercise Comparison — Calf Raise Range of Motion</h3>\n  <div class=\"reveal\" style=\"overflow-x:auto;\">\n    <table class=\"comparison-table\">\n      <thead><tr><th>Training Range</th><th>Medial Gastroc Growth</th><th>Best For</th></tr></thead>\n      <tbody>\n        <tr><td>Full Range of Motion</td><td>+6.7%</td><td>General Conditioning</td></tr>\n        <tr><td>Lengthened Partials (Stretch-Biased)</td><td>+15.2%</td><td>Maximum Calf Hypertrophy</td></tr>\n      </tbody>\n    </table>\n  </div>\n  <p class=\"source-note reveal\" style=\"margin-top:12px;\">Source: Kassiano et al. (2023), J Strength Cond Res 37(9):1746-1753 — 8-week trial in untrained women, ultrasound-measured medial gastrocnemius thickness.</p>\n  </div>\n</section>",
  "sources": "<section class=\"section sources-section\" id=\"sources\">\n  <div class=\"section-eyebrow reveal\">References</div>\n  <h2 class=\"section-title reveal\">Research <span class=\"accent\">Sources</span></h2>\n  <p class=\"section-subtitle reveal\">Peer-reviewed studies and practitioner breakdowns that inform the exercise selection, tempo, and intensity prescriptions across all 6 sessions — the same literature Jeff Nippard and Dr. Mike Israetel draw on for their own evidence-based programming.</p>\n\n  <p class=\"sources-core-note reveal\"><strong>Core science, applied to every day:</strong> these four sources underpin the universal tempo, RIR, and volume rules used across Push, Pull and Legs alike.</p>\n\n  <div class=\"source-card reveal\">\n    <div class=\"source-number\">01</div>\n    <div class=\"source-content\">\n      <h4>Schoenfeld, B.J. (2010). The Mechanisms of Muscle Hypertrophy and Their Application to Resistance Training.</h4>\n      <p>The foundational review defining mechanical tension, metabolic stress, and muscle damage as the three drivers of hypertrophy. Forms the theoretical basis for the tempo protocol used on every day of this program.</p>\n      <a class=\"source-link\" href=\"https://doi.org/10.1519/JSC.0b013e3181e840f3\" target=\"_blank\" rel=\"noopener\">View DOI &rarr;</a>\n    </div>\n  </div>\n\n  <div class=\"source-card reveal\">\n    <div class=\"source-number\">02</div>\n    <div class=\"source-content\">\n      <h4>Helms, E.R., Cronin, J., Storey, A., &amp; Zourdos, M.C. (2016). Application of the Repetitions in Reserve-Based Rating of Perceived Exertion Scale for Resistance Training.</h4>\n      <p>Introduced the RIR-based effort scale used throughout every session's intensity prescriptions, letting load autoregulate to daily readiness instead of chasing a fixed number on the bar.</p>\n      <a class=\"source-link\" href=\"https://pubmed.ncbi.nlm.nih.gov/27531969/\" target=\"_blank\" rel=\"noopener\">View on PubMed &rarr;</a>\n    </div>\n  </div>\n\n  <div class=\"source-card reveal\">\n    <div class=\"source-number\">03</div>\n    <div class=\"source-content\">\n      <h4>Grgic, J., Schoenfeld, B.J., Orazem, J., &amp; Sabol, F. (2022). Effects of Resistance Training Performed to Repetition Failure or Non-Failure on Muscular Strength and Hypertrophy.</h4>\n      <p>A meta-analysis of 11 studies concluding training to failure isn't required for hypertrophy — the basis for prescribing 1-2 RIR on most sets across all 6 days and reserving true failure for a handful of strategic moments per session.</p>\n      <a class=\"source-link\" href=\"https://pubmed.ncbi.nlm.nih.gov/33497853/\" target=\"_blank\" rel=\"noopener\">View on PubMed &rarr;</a>\n    </div>\n  </div>\n\n  <div class=\"source-card reveal\">\n    <div class=\"source-number\">04</div>\n    <div class=\"source-content\">\n      <h4>Schoenfeld, B.J., Ogborn, D., &amp; Krieger, J.W. (2017). Dose-Response Relationship Between Weekly Resistance Training Volume and Increases in Muscle Mass.</h4>\n      <p>The foundational meta-analysis establishing a graded, roughly linear relationship between weekly hard sets and hypertrophy — the basis for the weekly volume targets referenced throughout the Anatomy section.</p>\n      <a class=\"source-link\" href=\"https://doi.org/10.1080/02640414.2016.1210197\" target=\"_blank\" rel=\"noopener\">View DOI &rarr;</a>\n    </div>\n  </div>\n\n  <div class=\"group-tabs reveal\" id=\"sourcesTabs\" style=\"margin-top:12px;\">\n    <button class=\"group-tab\" data-tab-group=\"push\" onclick=\"switchSourcesTab('push')\">Push-Specific</button>\n    <button class=\"group-tab\" data-tab-group=\"pull\" onclick=\"switchSourcesTab('pull')\">Pull-Specific</button>\n    <button class=\"group-tab active\" data-tab-group=\"legs\" onclick=\"switchSourcesTab('legs')\">Legs-Specific</button>\n  </div>\n\n  <div class=\"sources-group-panel\" data-group=\"push\">\n\n    <div class=\"source-card reveal\">\n      <div class=\"source-number\">01</div>\n      <div class=\"source-content\">\n        <h4>Trebs, A.A., Brandenburg, J.P., &amp; Pitney, W.A. (2010). An Electromyography Analysis of 3 Muscles Surrounding the Shoulder Joint During a Chest Press at Several Angles.</h4>\n        <p>Compared pectoralis and deltoid activation across bench angles from 0° to 56°. Found the clavicular head peaks at a steep ~44° incline — the basis for the incline vs. flat exercise pairing in Push Day A/B.</p>\n        <a class=\"source-link\" href=\"https://scholar.google.com/scholar?q=Trebs+Brandenburg+Pitney+2010+electromyography+chest+press+angles\" target=\"_blank\" rel=\"noopener\">Find on Scholar &rarr;</a>\n      </div>\n    </div>\n\n    <div class=\"source-card reveal\">\n      <div class=\"source-number\">02</div>\n      <div class=\"source-content\">\n        <h4>Rodríguez-Ridao, D. et al. (2020). Effect of Five Bench Inclinations on the EMG Activity of the Pectoralis Major, Anterior Deltoid &amp; Triceps Brachii During the Bench Press.</h4>\n        <p>Tested 0°, 15°, 30°, 45° and 60°. Upper pec peaked near 30°, mid/lower pec peaked at 0° flat, and anterior deltoid activation rose steadily with steeper angles — directly informing the Day A/B angle split.</p>\n        <a class=\"source-link\" href=\"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC7579505/\" target=\"_blank\" rel=\"noopener\">View on PMC &rarr;</a>\n      </div>\n    </div>\n\n    <div class=\"source-card reveal\">\n      <div class=\"source-number\">03</div>\n      <div class=\"source-content\">\n        <h4>Maeo, S. et al. (2022). Triceps Brachii Hypertrophy Is Substantially Greater After Elbow Extension Training Performed in the Overhead Versus Neutral Arm Position.</h4>\n        <p>A 12-week MRI-tracked trial: overhead-position training produced 28.5% long-head growth vs. 19.6% neutral, even at a lighter absolute load — the core evidence behind pairing overhead extensions with pushdowns/kickbacks.</p>\n        <a class=\"source-link\" href=\"https://pubmed.ncbi.nlm.nih.gov/35819335/\" target=\"_blank\" rel=\"noopener\">View on PubMed &rarr;</a>\n      </div>\n    </div>\n\n    <div class=\"source-card reveal\">\n      <div class=\"source-number\">04</div>\n      <div class=\"source-content\">\n        <h4>Larsen, S., Wolf, M., Schoenfeld, B.J. et al. (2025). Dumbbell Versus Cable Lateral Raises for Lateral Deltoid Hypertrophy: An Experimental Study.</h4>\n        <p>An 8-week within-participant ultrasound trial finding dumbbell and cable lateral raises produced statistically equivalent lateral deltoid growth — supporting the use of both variations across the two sessions.</p>\n        <a class=\"source-link\" href=\"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC12277279/\" target=\"_blank\" rel=\"noopener\">View on PMC &rarr;</a>\n      </div>\n    </div>\n\n    <div class=\"source-card reveal\">\n      <div class=\"source-number\">05</div>\n      <div class=\"source-content\">\n        <h4>Jeff Nippard — Chest, Shoulder &amp; Triceps Hypertrophy Breakdowns (YouTube &amp; Science Applied Programs)</h4>\n        <p>Nippard's public breakdowns synthesize this same body of EMG and hypertrophy literature into practical programming — the exercise-selection philosophy Push Day's structure draws on.</p>\n        <a class=\"source-link\" href=\"https://www.jeffnippard.com/\" target=\"_blank\" rel=\"noopener\">Visit JeffNippard.com &rarr;</a>\n      </div>\n    </div>\n\n  </div>\n\n  <div class=\"sources-group-panel\" data-group=\"pull\">\n\n    <div class=\"source-card reveal\">\n      <div class=\"source-number\">01</div>\n      <div class=\"source-content\">\n        <h4>Andersen, V., Fimland, M.S., Wiik, E., Skoglund, A., &amp; Sæterbakken, A.H. (2014). Effects of Grip Width on Muscle Strength and Activation in the Lat Pull-Down.</h4>\n        <p>Compared narrow, medium, and wide pronated grips using 6RM loads and EMG. Found lat activation was remarkably similar across all three widths, challenging the popular belief that wider is always better for the lats.</p>\n        <a class=\"source-link\" href=\"https://www.researchgate.net/publication/261067362_Effects_of_Grip_Width_on_Muscle_Strength_and_Activation_in_the_Lat_Pull-Down\" target=\"_blank\" rel=\"noopener\">Find on ResearchGate &rarr;</a>\n      </div>\n    </div>\n\n    <div class=\"source-card reveal\">\n      <div class=\"source-number\">02</div>\n      <div class=\"source-content\">\n        <h4>Lusk, S.J., Hale, B.D., &amp; Russell, D.M. (2010). Grip Width and Forearm Orientation Effects on Muscle Activity During the Lat Pull-Down.</h4>\n        <p>Compared wide-pronated, wide-supinated, narrow-pronated, and narrow-supinated grips. Found a pronated grip activates the lats more than a supinated one, regardless of width — the basis for defaulting to pronated grips throughout Pull Day.</p>\n        <a class=\"source-link\" href=\"https://pure.psu.edu/en/publications/grip-width-and-forearm-orientation-effects-on-muscle-activity-dur/\" target=\"_blank\" rel=\"noopener\">View Publication &rarr;</a>\n      </div>\n    </div>\n\n    <div class=\"source-card reveal\">\n      <div class=\"source-number\">03</div>\n      <div class=\"source-content\">\n        <h4>Signorile, J.F., Zink, A.J., &amp; Szwed, S.P. (2002). A Comparative Electromyographical Investigation of Muscle Utilization Patterns Using Various Hand Positions During the Lat Pull-Down.</h4>\n        <p>Examined posterior deltoid, latissimus dorsi, pectoralis major, teres major, and triceps long head activity across pulldown hand positions — the underlying data behind pairing pulling movements with dedicated rear-delt isolation.</p>\n        <a class=\"source-link\" href=\"https://scholar.google.com/scholar?q=Signorile+Zink+Szwed+2002+lat+pull-down+hand+positions\" target=\"_blank\" rel=\"noopener\">Find on Scholar &rarr;</a>\n      </div>\n    </div>\n\n    <div class=\"source-card reveal\">\n      <div class=\"source-number\">04</div>\n      <div class=\"source-content\">\n        <h4>Oliveira, L.F., Matta, T.T., Alves, D.S., Garcia, M.A.C., &amp; Vieira, T.M.M. (2009). Effect of the Shoulder Position on the Biceps Brachii EMG in Different Dumbbell Curls.</h4>\n        <p>Found the greatest biceps brachii activation occurs when the muscle is worked at a longer length — the direct evidence behind prioritizing incline and behind-the-torso curl positions in this program.</p>\n        <a class=\"source-link\" href=\"https://pubmed.ncbi.nlm.nih.gov/24150552/\" target=\"_blank\" rel=\"noopener\">View on PubMed &rarr;</a>\n      </div>\n    </div>\n\n    <div class=\"source-card reveal\">\n      <div class=\"source-number\">05</div>\n      <div class=\"source-content\">\n        <h4>An Exploratory Study of Biceps Brachii Electromyographic Activity During Traditional Dumbbell Versus Bayesian Cable Curls (2025).</h4>\n        <p>A direct EMG comparison of the standard dumbbell curl against the behind-the-body \"Bayesian\" cable curl position — the specific study behind the Face-Away Bayesian Cable Curl programmed on Pull Day A.</p>\n        <a class=\"source-link\" href=\"https://www.mdpi.com/2813-0413/4/4/45\" target=\"_blank\" rel=\"noopener\">View Study &rarr;</a>\n      </div>\n    </div>\n\n    <div class=\"source-card reveal\">\n      <div class=\"source-number\">06</div>\n      <div class=\"source-content\">\n        <h4>Muscle Hypertrophy from Partial Repetition at Long vs. Short Muscle Length: A Systematic Review and Meta-Analysis (2025), Sport Sciences for Health.</h4>\n        <p>Found resistance training performed at longer muscle lengths produced significantly greater overall, distal, and central hypertrophy than training at shorter lengths — the basis for the deep-stretch pause built into every pull and curl in this program.</p>\n        <a class=\"source-link\" href=\"https://link.springer.com/10.1007/s11332-025-01586-5\" target=\"_blank\" rel=\"noopener\">View DOI &rarr;</a>\n      </div>\n    </div>\n\n    <div class=\"source-card reveal\">\n      <div class=\"source-number\">07</div>\n      <div class=\"source-content\">\n        <h4>Dr. Mike Israetel — Back &amp; Biceps Training Breakdowns (YouTube &amp; RP Strength)</h4>\n        <p>The source of the Cable Flexion Row's signature round-and-extend technique and the broader \"stretched muscle positions drive the most growth\" philosophy applied across this program's rowing and curling movements.</p>\n        <a class=\"source-link\" href=\"https://rpstrength.com/\" target=\"_blank\" rel=\"noopener\">Visit RP Strength &rarr;</a>\n      </div>\n    </div>\n\n    <div class=\"source-card reveal\">\n      <div class=\"source-number\">08</div>\n      <div class=\"source-content\">\n        <h4>Jeff Nippard — Back &amp; Biceps Hypertrophy Breakdowns (YouTube &amp; Science Applied Programs)</h4>\n        <p>Nippard's public breakdowns synthesize this same body of EMG and hypertrophy literature into practical programming — the exercise-selection philosophy Pull Day's structure draws on.</p>\n        <a class=\"source-link\" href=\"https://www.jeffnippard.com/\" target=\"_blank\" rel=\"noopener\">Visit JeffNippard.com &rarr;</a>\n      </div>\n    </div>\n\n  </div>\n\n  <div class=\"sources-group-panel active\" data-group=\"legs\">\n\n    <div class=\"source-card reveal\">\n      <div class=\"source-number\">01</div>\n      <div class=\"source-content\">\n        <h4>Maeo, S. et al. (2021). Greater Hamstrings Muscle Hypertrophy but Similar Damage Protection after Training at Long versus Short Muscle Lengths.</h4>\n        <p>A 12-week within-subject trial comparing seated (hip-flexed, long-length) to prone (hip-extended, short-length) leg curl training: +14.1% versus +9.3% whole-hamstring hypertrophy. Leg curls aren't currently programmed, but this is the same long-length principle behind using RDLs as the hamstrings' sole direct driver — and the case for adding a seated curl back in if you want more volume.</p>\n        <a class=\"source-link\" href=\"https://doi.org/10.1249/MSS.0000000000002523\" target=\"_blank\" rel=\"noopener\">View DOI &rarr;</a>\n      </div>\n    </div>\n\n    <div class=\"source-card reveal\">\n      <div class=\"source-number\">02</div>\n      <div class=\"source-content\">\n        <h4>Pedrosa, G.F. et al. (2022). Partial Range of Motion Training Elicits Favorable Improvements in Muscular Adaptations When Carried Out at Long Muscle Lengths.</h4>\n        <p>Found leg-extension training performed at the lengthened (initial-ROM) portion of the range produced greater vastus lateralis hypertrophy than the same volume trained at shorter angles — supporting the reclined leg-extension setup used on both days.</p>\n        <a class=\"source-link\" href=\"https://pubmed.ncbi.nlm.nih.gov/33977835/\" target=\"_blank\" rel=\"noopener\">View on PubMed &rarr;</a>\n      </div>\n    </div>\n\n    <div class=\"source-card reveal\">\n      <div class=\"source-number\">03</div>\n      <div class=\"source-content\">\n        <h4>Clark, D.R., Lambert, M.I., &amp; Hunter, A.M. (2019). Trunk Muscle Activation in the Back and Hack Squat at the Same Relative Loads.</h4>\n        <p>Found the hack squat requires significantly less trunk stabilization than the free barbell back squat. This program now uses the Back Squat as its primary quad/glute compound instead — quad and glute activation are broadly comparable between the two, and the extra trunk demand is a reasonable trade for a movement that needs no specialty machine.</p>\n        <a class=\"source-link\" href=\"https://doi.org/10.1519/JSC.0000000000002144\" target=\"_blank\" rel=\"noopener\">View DOI &rarr;</a>\n      </div>\n    </div>\n\n    <div class=\"source-card reveal\">\n      <div class=\"source-number\">04</div>\n      <div class=\"source-content\">\n        <h4>Kassiano, W. et al. (2023). Greater Gastrocnemius Muscle Hypertrophy After Partial Range of Motion Training Performed at Long Muscle Lengths.</h4>\n        <p>An 8-week ultrasound trial finding calf raises trained through the lengthened portion of the range produced 15.2% medial gastrocnemius growth versus 6.7% for full range of motion — direct support for the mandatory 2-second stretch hold on both calf variations.</p>\n        <a class=\"source-link\" href=\"https://pubmed.ncbi.nlm.nih.gov/37015016/\" target=\"_blank\" rel=\"noopener\">View on PubMed &rarr;</a>\n      </div>\n    </div>\n\n    <div class=\"source-card reveal\">\n      <div class=\"source-number\">05</div>\n      <div class=\"source-content\">\n        <h4>Jeff Nippard — Leg Hypertrophy Breakdowns (YouTube &amp; Science Applied Programs)</h4>\n        <p>Nippard's public breakdowns synthesize this same body of muscle-length and hypertrophy literature into practical programming — the exercise-selection philosophy Leg Day's structure draws on.</p>\n        <a class=\"source-link\" href=\"https://www.jeffnippard.com/\" target=\"_blank\" rel=\"noopener\">Visit JeffNippard.com &rarr;</a>\n      </div>\n    </div>\n\n  </div>\n\n</section>",
  "overlays": "<div class=\"rest-timer\" id=\"restTimer\">\n  <div>\n    <div class=\"rt-time\" id=\"rtTime\">1:30</div>\n    <div class=\"rt-label\">Rest</div>\n  </div>\n  <button class=\"rt-btn\" onclick=\"adjustRestTimer(-15)\" aria-label=\"Subtract 15 seconds\">−15</button>\n  <button class=\"rt-btn\" onclick=\"adjustRestTimer(15)\" aria-label=\"Add 15 seconds\">+15</button>\n  <button class=\"rt-close\" onclick=\"hideRestTimer()\" aria-label=\"Dismiss timer\">\n    <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><path d=\"M6 6l12 12M18 6L6 18\"/></svg>\n  </button>\n</div>\n\n<div class=\"rest-timer tempo-pacer\" id=\"tempoPacer\">\n  <div>\n    <div class=\"rt-time\" id=\"tpPhaseLabel\">Lower</div>\n    <div class=\"rt-label\" id=\"tpPhaseSeconds\">3s</div>\n  </div>\n  <button class=\"rt-close\" onclick=\"stopTempoPacer()\" aria-label=\"Stop tempo pacer\">\n    <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><path d=\"M6 6l12 12M18 6L6 18\"/></svg>\n  </button>\n</div>\n\n<div class=\"toast-stack\" id=\"toastStack\"></div>\n<!-- Visually hidden live region for milestone announcements (exercise\n     complete, PR) that a sighted user already gets via the checkmark\n     badge / PR badge — kept to meaningful moments only, not per-set-tap,\n     so it doesn't turn into 21 announcements over a workout. -->\n<div id=\"a11yLiveRegion\" aria-live=\"polite\" role=\"status\" style=\"position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0;\"></div>\n\n<button class=\"standards-fab\" id=\"standardsFab\" onclick=\"openStandardsModal()\" aria-label=\"Quick reference: rest, RIR and deload standards\">?</button>\n\n<div class=\"app-modal-overlay\" id=\"standardsModalOverlay\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Programming standards quick reference\">\n  <div class=\"app-modal\">\n    <button class=\"modal-close\" onclick=\"closeModal('standardsModalOverlay')\" aria-label=\"Close\">\n      <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><path d=\"M6 6l12 12M18 6L6 18\"/></svg>\n    </button>\n    <h3>Quick Reference</h3>\n    <div class=\"modal-standard-row\">\n      <h4>Rest Periods</h4>\n      <p>Heavy compounds &amp; singles: <strong style=\"color:var(--ink);\">2–3 min</strong>. Standard isolation: <strong style=\"color:var(--ink);\">60–90 sec</strong>. Superset pairs: <strong style=\"color:var(--ink);\">15–20 sec</strong> between A→B, then 90 sec after the pair.</p>\n    </div>\n    <div class=\"modal-standard-row\">\n      <h4>RIR (Reps in Reserve)</h4>\n      <p>0-1 RIR = pushing right up to the wall. 1-2 RIR = one clean rep left in the tank. FAILURE = absolute, 0 RIR, technical form breaks next rep.</p>\n    </div>\n    <div class=\"modal-standard-row\">\n      <h4>Double Progression</h4>\n      <p>Hit the top of the rep range at your target RIR on every set → add weight next session. Fall below the bottom of the range → hold the load and rebuild reps first.</p>\n    </div>\n    <div class=\"modal-standard-row\">\n      <h4>Deload — Every 6th Week</h4>\n      <p>Cut volume ~60% (drop 1-2 sets/exercise), stay 3+ RIR, skip all FAILURE/PEAK sets.</p>\n    </div>\n    <a href=\"#standards\" onclick=\"closeModal('standardsModalOverlay')\" style=\"display:inline-block;margin-top:8px;color:var(--accent-bright);font-size:13px;font-weight:600;\">Jump to full Standards section →</a>\n  </div>\n</div>\n\n<div class=\"app-modal-overlay\" id=\"historyModalOverlay\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Session history\">\n  <div class=\"app-modal\">\n    <button class=\"modal-close\" onclick=\"closeModal('historyModalOverlay')\" aria-label=\"Close\">\n      <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><path d=\"M6 6l12 12M18 6L6 18\"/></svg>\n    </button>\n    <h3>Session History</h3>\n    <div class=\"history-week-compare\">\n      <div class=\"history-week-stat\"><div class=\"num\" id=\"histThisWeek\">0</div><div class=\"lbl\">Sets This Week</div></div>\n      <div class=\"history-week-stat\"><div class=\"num\" id=\"histLastWeek\">0</div><div class=\"lbl\">Sets Last Week</div></div>\n    </div>\n    <div class=\"history-sparkline\" id=\"historySparkline\"></div>\n    <p style=\"font-size:12px;color:var(--ink-dim);\">Last 14 days · sets completed per day, stored locally in this browser.</p>\n  </div>\n</div>\n\n<div class=\"app-modal-overlay\" id=\"confirmModalOverlay\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Confirm action\">\n  <div class=\"app-modal confirm-modal\">\n    <button class=\"modal-close\" onclick=\"closeConfirmModal(false)\" aria-label=\"Cancel\">\n      <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><path d=\"M6 6l12 12M18 6L6 18\"/></svg>\n    </button>\n    <h3>Are you sure?</h3>\n    <p id=\"confirmModalMessage\"></p>\n    <div class=\"confirm-modal-actions\">\n      <button class=\"reset-btn\" onclick=\"closeConfirmModal(false)\">Cancel</button>\n      <button class=\"reset-btn confirm-danger-btn\" onclick=\"closeConfirmModal(true)\">Confirm</button>\n    </div>\n  </div>\n</div>"
} as const;

export type FragmentName = keyof typeof fragments;
